def _owned_session_file(path: Path) -> None:
    """Validate an exact retirement target without following links or reading credentials."""
    try:
        metadata = path.lstat()
    except FileNotFoundError:
        return
    if (not stat.S_ISREG(metadata.st_mode) or metadata.st_uid != os.getuid()
            or metadata.st_nlink != 1 or stat.S_IMODE(metadata.st_mode) != 0o600):
        raise ContractError("dogfood session record must be one owned private regular file")

def _dogfood_member_session_files() -> tuple[Path, Path]:
    # The shared recipe owns exactly these two files, not arbitrary operator input paths.
    root = Path.home() / ".weave" / "dogfood"
    for directory in (root.parent, root):
        if directory.is_symlink() or (directory.exists() and (
                not directory.is_dir() or directory.stat().st_uid != os.getuid()
                or stat.S_IMODE(directory.stat().st_mode) & 0o077)):
            raise ContractError("dogfood member session directory must be owned and private")
    files = (root / "functional-smoke-identities.json",
             root / "functional-smoke-identities.preparation-ledger.json")
    for path in files:
        _owned_session_file(path)
    return files


def _dogfood_reset_marker(context: ComposeContext) -> Path:
    for directory in (context.generated_root, context.generated_root / "operations"):
        if directory.is_symlink() or (directory.exists() and (
                not directory.is_dir() or directory.stat().st_uid != os.getuid())):
            raise ContractError("dogfood session directory must be owned and not a symlink")
    marker = context.generated_root / "operations" / "session-reset.pending.json"
    _owned_session_file(marker)
    return marker


def _require_complete_dogfood_session(context: ComposeContext) -> None:
    if context.environment == "dogfood" and _dogfood_reset_marker(context).exists():
        raise ContractError("dogfood-session-reset-incomplete")


def _sync_session_directory(path: Path) -> None:
    descriptor = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)

/**
 * Canonical context after an authoritative provider read, without minting a JWT or session.
 * Callers must have verified current membership, activation and subject through the existing
 * identity adapter. Setup never supplies a tenant or substitutes a requested role here.
 */
public OrganizationIdentityContext resolveVerifiedMember(
        String issuer, String subject, List<String> roles, List<String> groups) {
    if (!hasText(issuer) || !hasText(subject) || !hasText(configuredOrganizationId())
            || roles == null || roles.size() != 1 || roles.getFirst() == null || !WEAVE_ORG_ROLES.contains(roles.getFirst())
            || groups == null || groups.stream().anyMatch(group -> !hasText(group)
                || group.chars().anyMatch(Character::isISOControl))) {
        throw new ApiErrorException(HttpStatus.FORBIDDEN, "verified-member-context-invalid",
                "A current verified organization member is required.", Map.of("module", "identity"));
    }
    validateIdentitySegment(issuer, "iss", MAX_IDENTITY_ISSUER_LENGTH);
    validateIdentitySegment(subject, "sub", MAX_IDENTITY_SUBJECT_LENGTH);
    List<String> currentRoles = List.copyOf(roles);
    List<String> currentGroups = groups.stream().distinct().sorted().toList();
    return new OrganizationIdentityContext(configuredOrganizationId(), issuer, subject,
            IdentityReferences.primaryIdentityKey(issuer, subject), IdentityReferences.accountId(issuer, subject),
            currentRoles, currentGroups, List.of(), providerRoleMappings(currentRoles, currentGroups));
}

private final OrganizationIdentityContextResolver identities = OrganizationIdentityContextResolver.configured(
        new com.massimotter.weave.backend.config.ContextAuthorizationProperties(
                null, null, "org", null, null, null, null, null));

@Test
void verifiedProviderMemberUsesTheSameCanonicalIdentityWithoutImpersonation() {
    var token = jwt(Map.of("organization", Map.of("weave-dogfood", Map.of(
            "groups", List.of("/members", "/capabilities/weaver"),
            "resource_access", Map.of("weave-app", Map.of("roles", List.of("member")))))));
    var observed = resolver.resolveVerifiedMember(token.getIssuer().toString(), token.getSubject(),
            List.of("member"), List.of("/members", "/capabilities/weaver", "/members"));
    assertThat(observed).isEqualTo(resolver.resolve(token));
    assertThat(observed.organizationId()).isEqualTo("configured-default");
    assertThat(observed.contextRoles()).isEmpty();
    assertThat(observed.roles()).containsExactly("member");
}

@Test
void verifiedProviderContextRejectsMissingUnknownOrAmbiguousRoles() {
    for (List<String> roles : List.of(List.<String>of(), List.of("superadmin"), List.of("owner", "member"))) {
        assertThatThrownBy(() -> resolver.resolveVerifiedMember(
                "https://auth.example.invalid/realms/weave", "person-1", roles, List.of("/members")))
                .isInstanceOf(com.massimotter.weave.backend.exception.ApiErrorException.class);
    }
    assertThatThrownBy(() -> resolver.resolveVerifiedMember(
            "https://auth.example.invalid/realms/weave", "person-1", null, List.of()))
            .isInstanceOf(com.massimotter.weave.backend.exception.ApiErrorException.class);
}

@Test
void verifiedProviderContextDoesNotSynthesizeMissingIdentityOrGroups() {
    for (String subject : List.of("", "subject with spaces", "subject#other", "subject" + (char) 0)) {
        assertThatThrownBy(() -> resolver.resolveVerifiedMember(
                "https://auth.example.invalid/realms/weave", subject, List.of("member"), List.of("/members")))
                .isInstanceOf(com.massimotter.weave.backend.exception.ApiErrorException.class);
    }
    assertThatThrownBy(() -> resolver.resolveVerifiedMember(
            "", "person-1", List.of("member"), List.of()))
            .isInstanceOf(com.massimotter.weave.backend.exception.ApiErrorException.class);
    assertThatThrownBy(() -> resolver.resolveVerifiedMember(
            "https://auth.example.invalid/realms/weave", "person-1", List.of("member"), null))
            .isInstanceOf(com.massimotter.weave.backend.exception.ApiErrorException.class);
    assertThatThrownBy(() -> resolver.resolveVerifiedMember(
            "https://auth.example.invalid/realms/weave", "person-1", List.of("member"), List.of("/members\n")))
            .isInstanceOf(com.massimotter.weave.backend.exception.ApiErrorException.class);
}

private final OrganizationIdentityContextResolver identities = OrganizationIdentityContextResolver.configured(
        new com.massimotter.weave.backend.config.ContextAuthorizationProperties(
                null, null, "org:configured", null, null, null, null, null));
